import{_ as r,o,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Use + Dev Meetup March 2026","description":"","frontmatter":{"title":"Ceph Use + Dev Meetup March 2026","date":"2026-03-20T00:00:00.000Z","updated":"2026-03-21T00:00:00.000Z","tags":["Ceph","OSD","RBD","deep scrub","HDD"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_Use_+_Dev_Meetup_March_2026.md","filePath":"posts/2026/Ceph_Use_+_Dev_Meetup_March_2026.md","lastUpdated":1780459816000}'),l={name:"posts/2026/Ceph_Use_+_Dev_Meetup_March_2026.md"};function s(n,e,i,p,d,c){return o(),t("div",null,[...e[0]||(e[0]=[a('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 Ceph Use + Dev Meetup 于 2026 年 3 月举行，采用开放讨论形式，与会者就社区活动、已知 bug 及性能调优等议题展开交流。</p><h2 id="议题一-ceph-day-london-征稿通知" tabindex="-1">议题一：Ceph Day London 征稿通知 <a class="header-anchor" href="#议题一-ceph-day-london-征稿通知" aria-label="Permalink to &quot;议题一：Ceph Day London 征稿通知&quot;">​</a></h2><p>社区组织者 Lee Sanders宣布 Ceph Day London 的 Call for Papers（CFP）正式开放。活动将于 <strong>6 月 17 日</strong>在伦敦举办，征稿截止日期为 <strong>4 月 24 日</strong>。</p><p>征稿方向包括：</p><ul><li>用户实际使用案例（use cases）与用户故事</li><li>performance 测试与优化经验</li><li>新功能开发进展</li><li>任何与 Ceph 上游社区相关的内容</li></ul><p>有意投稿者可发送邮件至 <strong>londonsef.io</strong> 咨询。</p><p>此外，主持人还提醒与会者，<strong>Ceph Days Raleigh</strong> 将于下周举行，尚未注册的用户仍可报名参加。</p><h2 id="议题二-rbd-clone-展平后读取返回零的-bug" tabindex="-1">议题二：RBD clone 展平后读取返回零的 Bug <a class="header-anchor" href="#议题二-rbd-clone-展平后读取返回零的-bug" aria-label="Permalink to &quot;议题二：RBD clone 展平后读取返回零的 Bug&quot;">​</a></h2><p>用户 Laura 汇报了一个与 RBD clone flattening 相关的 bug（已创建 tracker）。</p><p><strong>问题描述：</strong> 当客户端正在访问一个 clone snapshot 时，若该 clone 被并发执行 flatten 操作，后续的读取请求将全部返回零值，直到客户端将该 clone snapshot 执行 unmap/unmount 并重新 remap/remount 后才恢复正常。</p><p><strong>影响范围：</strong></p><ul><li>初步判断影响 Squid（tentacle）等近期版本，可能在更早版本及 main 分支上同样存在</li><li>该问题已由 Nikola 完成初步调查，但尚无 PR 提交，需要进一步 code review</li></ul><p><strong>后续行动：</strong></p><ul><li>请求在 tracker 中补充复现所用的具体版本信息，以便提高 reproducibility</li><li>主持人将把该 issue 转发给 RBD 团队（Ilia 等）进行评估</li><li>感谢 MLA 在 ticket 中补充了复现步骤</li></ul><h2 id="议题三-大容量-hdd-上的-deep-scrub-性能问题" tabindex="-1">议题三：大容量 HDD 上的 deep scrub 性能问题 <a class="header-anchor" href="#议题三-大容量-hdd-上的-deep-scrub-性能问题" aria-label="Permalink to &quot;议题三：大容量 HDD 上的 deep scrub 性能问题&quot;">​</a></h2><p>用户 Alexandra 提出了在大容量 HDD（如 26 TB）上执行 deep scrub 时遭遇的性能瓶颈问题。</p><p><strong>问题背景：</strong></p><ul><li>用户正在使用带有独立 DB volume 的大容量 HDD（26 TB）部署 Ceph（BlueStore 配置）</li><li>deep scrub 对 HDD 而言本质上是随机读（random read）操作</li><li>在实际负载下（如 CephFS 存储用户数据），HDD 的随机读性能仅约 <strong>10~20 MB/s</strong></li><li>Ceph 默认的 <code>osd_deep_scrub_interval</code> 为 <strong>1 周</strong>，在如此大容量的 HDD 上根本无法在一周内完成一次完整的 deep scrub</li></ul><p><strong>讨论要点：</strong></p><p>Anthony 指出：</p><ul><li>在此场景下，将 <code>osd_deep_scrub_interval</code> 调大（如改为 1 个月）是常见的应对方式，但会降低 deep scrub 的保护效果，属于 tradeoff</li><li>使用 replication 而非 erasure coding 的集群可以承受更高频率的 scrub</li><li>当 <strong>MCLOCK</strong> 调度器正确配置并生效时，该问题会有所缓解；而使用 <strong>WPQ</strong> 调度器时，问题会更为突出</li><li>scrub 速度受限的另一个原因是 <strong>PG 粒度的 reservation 机制</strong>：scrub 需要对该 PG 所涉及的所有 OSD 申请 reservation，容易产生&quot;gridlock&quot;，导致实际吞吐远低于 HDD 的顺序读上限（70~100 MB/s）</li></ul><p><strong>PG 数量调优建议：</strong></p><ul><li>若使用 PG autoscaler 默认参数，每个 OSD 的 PG 数可能仅约 60，导致单个 PG 体积过大，加剧 scrub 耗时</li><li>建议将每 OSD 的 PG 数调整至 <strong>150~200</strong></li><li>可通过调整 <code>mon_max_pg_per_osd</code> 和 <code>mon_target_pg_per_osd</code> 参数实现</li><li>Alexandra 确认该集群已禁用 autoscaler，当前每 OSD 约有 100 个 PG</li></ul><p><strong>行业趋势补充：</strong></p><ul><li>Seagate 已有最高 <strong>44 TB</strong> 的 HDD 即将上市，HDD 容量持续增大将使该问题愈发突出</li><li>有观点认为默认值应随 HDD 容量动态调整，或为 HDD 与 SSD 设置不同的默认值，但修改默认值较为复杂，需谨慎评估</li></ul><p><strong>后续行动：</strong></p><ul><li>Alexandra 将与 Anthony 线下沟通（Ceph Slack 或邮件），进一步排查该集群的具体配置并寻求调优方案</li></ul><h2 id="会议总结与展望" tabindex="-1">会议总结与展望 <a class="header-anchor" href="#会议总结与展望" aria-label="Permalink to &quot;会议总结与展望&quot;">​</a></h2><p>本次会议为开放讨论形式，议题较为轻松。主持人表示，未来的 userdev meetup 计划恢复针对 Ceph 核心支柱（如用户体验、performance 优化等）的专项议题讨论，并将通过 Slack 频道或用户邮件列表进一步征集议题和参与者。</p>',30)])])}const _=r(l,[["render",s]]);export{h as __pageData,_ as default};
